Code <pre><code>let fluffy;

function setup() {
  createCanvas(400, 400);
  fluffy = new Dog(200, 200, "WOOF!");
}

function draw() {
  background(220);

  fluffy.show();

  if (mouseIsPressed) {
    fluffy.bark();
  }
}

class Dog {
  constructor(x, y, barkSound) {
    this.x = x;
    this.y = y;
    this.barkSound = barkSound;
  }

  show() {
    noStroke();
    textAlign(CENTER);
    textSize(50);
    text("🐶", this.x, this.y);
  }

  bark() {
    textAlign(CENTER);
    textSize(10);
    text(this.barkSound, this.x, this.y - 50);
  }
}
