Code <pre><code>let bubbles = [];
let setTimer = 1000;
let timer = 0;
let score = 0;
let losses = 0;
let highScore = 0;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background("#1B3149");

  if (losses &gt; 4) {
    losses = 0;
    if (score &gt; highScore) {
      highScore = score;
    }
    score = 0;
    bubbles = [];
    timer = 1000;
  }

  if (timer &lt;= 0) {
    timer = setTimer;
    bubbles.push(new Bubble(random(width), 0 - height / 2));
  } else {
    timer -= deltaTime;
  }

  for (let i = 0; i &lt; bubbles.length; i++) {
    bubbles[i].update();
  }

  for (let i = 0; i &lt; bubbles.length; i++) {
    if (bubbles[i].y - bubbles[i].radius &gt; height) {
      bubbles.splice(i, 1);
      losses++;
    }
  }

  textSize(30);

  fill("red");
  textAlign(LEFT, TOP);
  text(losses, 0, 0);

  fill(255);
  textAlign(RIGHT, TOP);
  text(score, width, 0);

  textSize(20);

  fill(255);
  textAlign(CENTER, TOP);
  text("High Score = " + highScore, width / 2, 0);
}

function mousePressed() {
  for (let i = 0; i &lt; bubbles.length; i++) {
    if (bubbles[i].checkPop() == true) {
      bubbles.splice(i, 1);
      score++;
    }
  }
}

class Bubble {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.ySpeed = random(1, 5);
    this.radius = int(random(20, 30));
  }

  update() {
    noStroke();

    fill("#99C5C9");
    circle(this.x, this.y, this.radius * 2);

    fill(255);
    circle(this.x - this.radius / 4, this.y - this.radius / 4, this.radius / 2);

    this.y += this.ySpeed;
  }

  checkPop() {
    if (dist(mouseX, mouseY, this.x, this.y) &lt; this.radius) {
      return true;
    } else {
      return false;
    }
  }
}
